  function recoveryRecord(value){return object(value)&&uuid(value.tenant_id)&&hash(value.account_scope)&&uuid(value.idempotency_key)&&['review','cancel'].includes(value.kind)&&(value.kind==='cancel'?uuid(value.send_id):value.send_id===null)&&typeof value.confirming==='boolean';}
  function navigationState(){try{const value=history.state?.[historyKey];return recoveryRecord(value)?{[historyKey]:Object.fromEntries(recoveryFields.map(key=>[key,value[key]]))}:{};}catch{return {};}}
  function clearRecovery(){try{const next={...history.state};delete next[historyKey];history.replaceState(next,'',location.href);}catch{}}
  function clearContext(){clearRecovery();try{const url=new URL(location.href);if(url.searchParams.get('aba')==='enviar-mensagem'){url.searchParams.delete('message_id');history.replaceState({...history.state},'',url.pathname+url.search+url.hash);}}catch{}active?.invalidate?.();}
  function errorMessage(error,reading=false){const status=Number(error?.status);if([400,413,422].includes(status)&&typeof error.message==='string'&&error.message.length<=600)return error.message;return ({401:'Sua sessão expirou. Entre novamente no Orion.',403:'O acesso a Enviar Mensagem desta empresa não está disponível.',404:'Este pedido não foi localizado nesta consulta.',409:'Os dados ou a autorização mudaram. Consulte o mesmo pedido antes de continuar.',410:'A revisão expirou. Consulte o resultado antes de preparar outra.',429:'Aguarde um momento antes de consultar novamente.'})[status]||(reading?'Não foi possível consultar os dados. Tente novamente.':'Não foi possível confirmar a resposta. Consulte o mesmo pedido; o envio não será repetido automaticamente.');}
  function normalizedPhone(value){const digits=String(value||'').trim().replace(/[+\s().-]/g,'');if(!/^\+?[\d\s().-]+$/.test(String(value||'').trim())||!/^[1-9]\d{7,14}$/.test(digits))throw Error('Informe um número com código do país e de 8 a 15 dígitos.');return digits;}
