    const drafts=newDrafts(),state={alive:true,epoch:0,read:0,view:'form',target:null,options:null,detail:null,drafts,draft:drafts.text,loading:false,busy:false,revoked:false,error:'',notice:'',pending:null,operation:null,unresolved:false,missing:false,correcting:false,accountScope:null,dialog:null,contacts:null,contactQuery:'',contactPage:1,contactRead:0,contactLabels:new Map(),contactsLoading:false,contactsError:'',emoji:null,selection:{start:0,end:0},uploadPending:null};
    const fields=window.OrionFields,releaseFields=fields?.bind(host)||(()=>{}),controllers=new Map(),readers=new Set();let pollTimer=null,lastTrigger=null;
    const current=(epoch=state.epoch)=>state.alive&&epoch===state.epoch&&host.isConnected&&!state.revoked&&(typeof bridge.canAccess!=='function'||bridge.canAccess());
    const writable=()=>current()&&!!state.accountScope&&typeof crypto.randomUUID==='function'&&(typeof bridge.canWrite==='function'?bridge.canWrite():bridge.canWrite!==false);
